<script setup>
import { onMounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import * as api from '../api/notifications';
const { t, locale } = useI18n(); const rows = ref([]), loading = ref(true), busy = ref(false), error = ref(false), saved = ref(false);
async function load() { loading.value = true; error.value = false; try { rows.value = await api.fetchPreferences(); } catch { error.value = true; } finally { loading.value = false; } }
async function save() { busy.value = true; error.value = false; saved.value = false; try { rows.value = await api.savePreferences(rows.value.map(({ type, in_app, email, digest }) => ({ type, in_app, email, digest }))); saved.value = true; } catch { error.value = true; } finally { busy.value = false; } }
onMounted(load);
</script>
<template><section class="mx-auto max-w-4xl space-y-4 p-4 sm:p-6" :dir="locale === 'ar' ? 'rtl' : 'ltr'"><h1 class="text-2xl font-black">{{ t('notifications.preferences') }}</h1><p class="text-sm text-slate-600">{{ t('notifications.mandatoryHint') }}</p><p v-if="loading" role="status">{{ t('notifications.loading') }}</p><p v-if="error" role="alert" class="text-red-700">{{ t('notifications.error') }} <button type="button" class="min-h-11 underline" @click="load">{{ t('notifications.retry') }}</button></p><p v-if="saved" role="status" class="text-green-700">{{ t('notifications.saved') }}</p><form class="space-y-3" @submit.prevent="save"><fieldset v-for="row in rows" :key="row.type" class="rounded-2xl border border-slate-200 bg-white p-4" :disabled="busy"><legend class="px-2 text-sm font-bold">{{ row[locale] }} <span v-if="row.mandatory">· {{ t('notifications.mandatory') }}</span></legend><div class="flex flex-wrap gap-5"><label class="flex min-h-11 items-center gap-2"><input v-model="row.in_app" type="checkbox" :disabled="row.mandatory">{{ t('notifications.inApp') }}</label><label class="flex min-h-11 items-center gap-2"><input v-model="row.email" type="checkbox" :disabled="row.mandatory_email">{{ t('notifications.email') }}</label><label class="flex min-h-11 items-center gap-2"><input v-model="row.digest" type="checkbox" :disabled="row.mandatory || !row.email">{{ t('notifications.digest') }}</label></div></fieldset><button class="min-h-11 rounded-xl bg-primary px-6 text-brand-dark" :disabled="loading || busy">{{ t('notifications.save') }}</button></form></section></template>
